"""Small generated bytes only: process death, integrity and exact restoration."""
import io
import json
import multiprocessing
import os
from pathlib import Path
import tempfile
import unittest

import numpy as np
import torch

from .store import Store
from .codec import hashed,MAX_DEPTH


def files(step):
    rng=np.random.default_rng(439)
    tensor=torch.from_numpy((rng.normal(size=8192).astype('float32')+step*.00001).astype('float32'))
    out=io.BytesIO();torch.save({'model':tensor,'alias':tensor[3:900],
        'bits':torch.tensor([0x80000000,0x7fc00001,0x7f800000],dtype=torch.int64).to(torch.int32).view(torch.float32),
        'cursor':step,'history':list(range(step))},out)
    return {'state.pt':out.getvalue(),'record.json':json.dumps({'step':step}).encode(),
            'intent.json':json.dumps({'planned_step':step}).encode()}


def add(store,step,*,fault=lambda phase:None):
    f=files(step)
    with store.transaction('toy',step,f['intent.json'],b'fixed contract',fault=fault) as tx:tx.commit(f)


def killed_writer(path,phase):
    store=Store(path)
    def fault(point):
        if point==phase:os._exit(71)
    add(store,1,fault=fault)
    os._exit(0)


class Storage(unittest.TestCase):
    def setUp(self):self.temp=tempfile.TemporaryDirectory();self.root=Path(self.temp.name)
    def tearDown(self):self.temp.cleanup()

    def test_all_bytes_aliases_and_bounded_random_reads(self):
        for layout in ['chunk-zlib','zip-xor']:
            s=Store(self.root/layout,layout=layout)
            for step in range(9):add(s,step)
            rows=s.frames('toy')
            for step in np.random.default_rng(77).permutation(9):
                for key,value in files(int(step)).items():self.assertEqual(s.decode_file(rows[step],key),value)
            self.assertLessEqual(s.db.execute('SELECT max(depth) FROM objects').fetchone()[0],MAX_DEPTH)
            if layout=='zip-xor':self.assertGreater(s.db.execute("SELECT count(*) FROM objects WHERE codec='xor-zlib'").fetchone()[0],0)
            s.checkpoint();s.close()

    def test_writer_lease_and_committed_reader_visibility(self):
        s=Store(self.root/'lease',layout='zip-xor');add(s,0);other=Store(self.root/'lease')
        f=files(1)
        with s.transaction('toy',1,f['intent.json'],b'fixed contract') as tx:
            self.assertEqual(len(other.frames('toy')),1)
            with self.assertRaisesRegex(ValueError,'Another writer'):
                with other.transaction('toy',1,f['intent.json'],b'fixed contract'):pass
            tx.commit(f)
        self.assertEqual(len(other.frames('toy')),2);other.close();s.close()

    def test_process_crash_all_publication_boundaries(self):
        for phase in ['after_intent','after_objects','before_publish','after_publish']:
            with self.subTest(phase=phase):
                path=self.root/phase;s=Store(path,layout='zip-xor');add(s,0);s.close()
                child=multiprocessing.get_context('spawn').Process(target=killed_writer,args=(str(path),phase));child.start();child.join(20)
                self.assertFalse(child.is_alive());self.assertEqual(child.exitcode,71)
                s=Store(path);rows=s.frames('toy');self.assertEqual(len(rows),2 if phase=='after_publish' else 1)
                self.assertEqual(s.decode_file(rows[0],'state.pt'),files(0)['state.pt'])
                with self.assertRaisesRegex(ValueError,'Next step|pending intent'):add(s,1)
                if phase!='after_publish':
                    self.assertIsNotNone(s.db.execute('SELECT * FROM intents').fetchone())
                    self.assertEqual(s.db.execute('SELECT count(*) FROM objects').fetchone()[0],
                                     Store_count_objects_without_failure(path))
                s.close()

    def test_payload_corruption_never_returns_a_checkpoint(self):
        s=Store(self.root/'bad',layout='zip-xor');add(s,0);frame=s.frames('toy')[0]
        key=frame['files']['state.pt']['segments'][0]['object']
        s.db.execute('UPDATE objects SET payload=? WHERE sha=?',(b'CORRUPT',key))
        with self.assertRaisesRegex(ValueError,'checksum'):s.decode_file(frame,'state.pt')
        s.close()

    def test_truncated_object_and_frame_hash_failure(self):
        s=Store(self.root/'truncated',layout='zip-xor');add(s,0);frame=s.frames('toy')[0]
        key=frame['files']['state.pt']['segments'][-1]['object'];payload=s.db.execute('SELECT payload FROM objects WHERE sha=?',(key,)).fetchone()[0]
        s.db.execute('UPDATE objects SET payload=? WHERE sha=?',(payload[:-1],key))
        with self.assertRaises(ValueError):s.decode_file(frame,'state.pt')
        s.db.execute('UPDATE frames SET manifest=?',(b'{}',))
        with self.assertRaisesRegex(ValueError,'checksum'):s.frames('toy')
        s.close()

    def test_reserve_failure_retains_intent_and_old_frame(self):
        s=Store(self.root/'cap',layout='zip-xor');add(s,0);s.max_bytes=1
        with self.assertRaisesRegex(ValueError,'reserve cap'):add(s,1)
        self.assertEqual(len(s.frames('toy')),1)
        with self.assertRaisesRegex(ValueError,'pending intent'):add(s,1)
        s.close()

    def test_contract_cursor_seal_and_no_constructor_reentry(self):
        s=Store(self.root/'binding',layout='zip-xor');add(s,0)
        with self.assertRaisesRegex(ValueError,'contract'):
            with s.transaction('toy',1,files(1)['intent.json'],b'changed'):pass
        with self.assertRaisesRegex(ValueError,'Next step'):add(s,3)
        s.seal('toy',b'original done');self.assertEqual(len(s.frames('toy')),1)
        with self.assertRaisesRegex(ValueError,'Sealed'):add(s,1)
        # Storage inspection/decoding has no model constructor or forward.
        original=torch.nn.Module.__call__
        def forbidden(*a,**k):raise AssertionError('unexpected neural call')
        torch.nn.Module.__call__=forbidden
        try:self.assertEqual(s.decode_file(s.frames('toy')[0],'state.pt'),files(0)['state.pt'])
        finally:torch.nn.Module.__call__=original
        s.close()


def Store_count_objects_without_failure(path):
    # Independent replay fixture establishes there are no rolled-back objects.
    with tempfile.TemporaryDirectory() as directory:
        s=Store(Path(directory)/'control',layout='zip-xor');add(s,0)
        n=s.db.execute('SELECT count(*) FROM objects').fetchone()[0];s.close();return n


if __name__=='__main__':unittest.main()
